export function PresenceMap() {
  const present = COUNTRY_PATHS.filter((c) => c.present);
  const base = COUNTRY_PATHS.filter((c) => !c.present);
  return (
    <svg
      viewBox="0 0 660 860"
      role="img"
      aria-label={`Map of the ${present.length} countries where Convert Group operates: ${present.map((c) => c.name).join(", ")}.`}
      className="h-auto w-full"
    >
      <g fill="var(--cg-pale-blue)" opacity="0.16" stroke="var(--cg-navy)" strokeWidth="0.4">
        {base.map((c) => (
          <path key={c.name} d={c.d}>
            <title>{c.name}</title>
          </path>
        ))}
      </g>
      <g fill="var(--cg-cyan)" stroke="var(--cg-navy)" strokeWidth="0.4">
        {present.map((c) => (
          <path key={c.name} d={c.d}>
            <title>{c.name}</title>
          </path>
        ))}
      </g>
    </svg>
  );
}
